package crypto

import (
	"bytes"
	"crypto/rand"
	"crypto/rsa"
	"crypto/x509"
	"encoding/pem"
	"os"
	"path/filepath"
	"testing"
)

func TestNewRSACryptor(t *testing.T) {
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	keyFile := filepath.Join(t.TempDir(), "test.key")
	if err := os.WriteFile(keyFile, pem.EncodeToMemory(&pem.Block{
		Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key),
	}), 0600); err != nil {
		t.Fatal(err)
	}
	cryptor, err := NewRSACryptor(keyFile)
	if err != nil {
		t.Fatal(err)
	}
	testData := []byte("rsa 2048 key!!!!")
	decrypted := cryptor.Decrypt(cryptor.Encrypt(testData))
	if !bytes.Equal(decrypted, testData) {
		t.Fatalf("RSA round trip failed")
	}
}
